$(document).ready(function() {
  $("#enter").modal('show');
  function feature(){
    var top = $('#slideshow').offset().top + $(window).outerHeight() ;
    $(window).scroll(function(){
      if($(this).scrollTop() > top){
        if ($("#nine-feature").hasClass('open')) {

        }else{
          $("#nine-feature").click();
          $("#nine-feature").addClass('open')
        }

      }else{
        $(".nk-navbar-overlay").click();
        $("#nine-feature").removeClass('open')
      }
    }) 
  }
  feature();

});
$(document).on('click', '.first-scroll', function (event) {
    event.preventDefault();

    $('html, body').animate({
        scrollTop: $($.attr(this, 'href')).offset().top
    }, 500);
});

$(document).ready(function() {
  var success = $("#toastr").data('success')

  var error = $("#toastr").data('error')
  toastr.options = {
    closeButton : true,
    debug : false,
    progressBar : false,
    positionClass : "toast-top-right",
    onclick : null,
    showDuration : "300",
    hideDuration : "1000",
    timeOut : "4000",
    extendedTimeOut : "1000",
    showEasing : "swing",
    hideEasing : "linear",
    showMethod : "fadeIn",
    hideMethod : "fadeOut"
  };
  if (success != "") {
    toastr.success(success);
  }
  if (error != "") {
    toastr.error(error);
  }
});

