    zipcodeIntoDistrict: false,
  });
});

$(document).ready(function () {
  $.extend($.validator.messages, {
    required: "此欄位為必填",
    email: "請輸入有效的電子郵件地址",
    // 可以繼續添加其他默認信息的翻譯
  });

  const config = {
    rules: {
      "inquiry[name]": {
        required: true,
      },
      "inquiry[mobile]": {
        required: true,
      },
      // "inquiry[email]": {
      //   required: true,
      //   email: true,
      // },
      "inquiry[content]": {
        required: true,
      },
      "inquiry[agree_privacy]": {
        required: true,
      },
    },
    messages: {
      "inquiry[name]": {
        required: "請輸入姓名",
      },
      "inquiry[mobile]": {
        required: "請輸入手機號碼",
      },
      // "inquiry[email]": {
      //   required: "請輸入E-mail",
      //   email: "請輸入正確的E-mail格式",
      // },
      "inquiry[content]": {
        required: "請描述您的問題或需求",
      },
      "inquiry[agree_privacy]": {
        required: "請同意隱私權聲明",
      },
    },
    highlight: function (element) {
      const label = $(element).closest("li").find(".field-label");
      label.addClass("error");
    },
    unhighlight: function (element) {
      const label = $(element).closest("li").find(".field-label");
      label.removeClass("error");
    },
    errorPlacement: function (error, element) {
      if (element.attr("type") === "checkbox") {
        error.insertAfter(element.parent("div"));
      } else {
        error.insertAfter(element);
      }
    },
  };

  // $("#inquiry-company").validate(config)
  $("#inquiry-personal").validate(config);
});

